import type { CourseRepository } from '../contracts/services';
import type { Course, Hole } from './types';
import { ancientTempleCourse } from './data/ancient-temple';
import { arcticBaseCourse } from './data/arctic-base';
import { candyFactoryCourse } from './data/candy-factory';
import { chaosDimension } from './data/chaos-dimension';
import { greenHillsCourse } from './data/green-hills';
import { hauntedMansion } from './data/haunted-mansion';
import { neonCity } from './data/neon-city';
import { pirateBayCourse } from './data/pirate-bay';
import { spaceStation } from './data/space-station';
import { volcanoCourse } from './data/volcano';

/** Deterministic random source; injected in tests. */
export type CourseRandom = () => number;

/** Every playable course, ordered from gentle to chaotic for menus and tours. */
export const COURSES: readonly Course[] = [
  greenHillsCourse,
  pirateBayCourse,
  candyFactoryCourse,
  ancientTempleCourse,
  arcticBaseCourse,
  hauntedMansion,
  neonCity,
  spaceStation,
  volcanoCourse,
  chaosDimension,
];

const registry = new Map<string, Course>();
for (const course of COURSES) {
  if (registry.has(course.id)) throw new Error(`Duplicate course id "${course.id}" in the course registry`);
  registry.set(course.id, course);
}

/** Course lookup table keyed by course id. */
export const COURSE_REGISTRY: ReadonlyMap<string, Course> = registry;

/** Course used when no valid selection was requested. */
export const DEFAULT_COURSE_ID: string = COURSES[0]!.id;

/** Pseudo id accepted by selectors and URLs to roll a random course. */
export const RANDOM_COURSE_ID = 'random';

export interface CourseSummary {
  id: string;
  name: string;
  themeId: string;
  holeCount: number;
  totalPar: number;
}

/** Lightweight data for menus, so UI code never walks full hole descriptors. */
export const COURSE_SUMMARIES: readonly CourseSummary[] = COURSES.map(course => ({
  id: course.id,
  name: course.name,
  themeId: course.themeId,
  holeCount: course.holes.length,
  totalPar: course.holes.reduce((sum, hole) => sum + hole.par, 0),
}));

export function listCourses(): readonly Course[] {
  return COURSES;
}

export function hasCourse(courseId: string | undefined): boolean {
  return courseId !== undefined && registry.has(courseId);
}

export function getCourse(courseId: string | undefined): Course | undefined {
  return courseId === undefined ? undefined : registry.get(courseId);
}

export function requireCourse(courseId: string): Course {
  const course = registry.get(courseId);
  if (!course) throw new Error(`Unknown course "${courseId}". Known courses: ${[...registry.keys()].join(', ')}`);
  return course;
}

export function pickRandomCourse(random: CourseRandom = Math.random): Course {
  const index = Math.min(COURSES.length - 1, Math.max(0, Math.floor(random() * COURSES.length)));
  return COURSES[index]!;
}

/** Launch-option shaped request: `?course=<id>&hole=<1-based>`. */
export interface CourseSelectionRequest {
  courseId?: string;
  hole?: number;
}

export interface CourseSelection {
  course: Course;
  hole: Hole;
  /** Zero-based index inside `course.holes`. */
  holeIndex: number;
  /** One-based hole number shown in HUD and URLs. */
  holeNumber: number;
  /** False when the request fell back to the default course. */
  matchedCourse: boolean;
  /** False when the requested hole was missing or out of range. */
  matchedHole: boolean;
}

/** Resolves a menu or URL request into a concrete course and starting hole. */
export function resolveCourseSelection(
  request: CourseSelectionRequest = {},
  random: CourseRandom = Math.random,
): CourseSelection {
  const requested = request.courseId?.trim();
  const isRandom = requested === RANDOM_COURSE_ID;
  const course = isRandom ? pickRandomCourse(random) : getCourse(requested) ?? requireCourse(DEFAULT_COURSE_ID);
  const requestedHole = request.hole;
  const matchedHole =
    requestedHole !== undefined &&
    Number.isInteger(requestedHole) &&
    requestedHole >= 1 &&
    requestedHole <= course.holes.length;
  const holeIndex = matchedHole ? requestedHole - 1 : 0;
  return {
    course,
    hole: course.holes[holeIndex]!,
    holeIndex,
    holeNumber: holeIndex + 1,
    matchedCourse: isRandom || (requested !== undefined && course.id === requested),
    matchedHole,
  };
}

/** Bundled course source implementing the async repository contract. */
export class LocalCourseRepository implements CourseRepository {
  async listCourses(): Promise<readonly Course[]> {
    return COURSES;
  }

  async getCourse(courseId: string): Promise<Course> {
    return requireCourse(courseId);
  }
}
